export function CssGrid({
  columns = "{{columns}}",
  justifyItems = "{{justifyItems}}",
  gap = {{gap}},
  span = {{span}},
}) {
  const cell = { borderRadius: 8, padding: "14px 8px", fontWeight: 700, textAlign: "center" };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="CSS Grid: six cells arranged in a two-dimensional grid, first cell optionally spanning two columns">
      <div style={{ display: "grid", gridTemplateColumns: columns, justifyItems, gap }}>
        <div style={{ ...cell, background: "#F5C2E0", ...(span ? { gridColumn: "span 2" } : {}) }}>1{span ? " span 2" : ""}</div>
        <div style={{ ...cell, background: "#A8E6C1" }}>2</div>
        <div style={{ ...cell, background: "#A8E6C1" }}>3</div>
        <div style={{ ...cell, background: "#A8E6C1" }}>4</div>
        <div style={{ ...cell, background: "#A8E6C1" }}>5</div>
        <div style={{ ...cell, background: "#A8E6C1" }}>6</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        columns: {columns} &middot; justify-items: {justifyItems} &middot; gap {gap}px
      </p>
    </div>
  );
}
